CPC_QUESTIONS.push({"id":"fcc-cpc-261698","sourceQuestionId":"261698","t":"cpc-m10","moduleId":"cpc-m10","q":"No processo \"A\" as partes pretendem requerer por livre e espontânea vontade a suspensão do feito. No Código de Processo Civil, a suspensão do processo por convecção das partes","o":["não é prevista.","é permitida pelo prazo máximo de seis meses.","é proibida expressamente.","é permitida pelo prazo máximo de três meses.","é permitida pelo prazo máximo de trinta dias."],"a":1,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRE RR/TRE RR/Judiciária/2015 • TEC 261698","source":"FCC - AJ TRE RR/TRE RR/Judiciária/2015","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/261698","year":2015,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-315362","sourceQuestionId":"315362","t":"cpc-m10","moduleId":"cpc-m10","q":"No tocante à suspensão e à extinção do processo, considere: I. A suspensão do processo por convenção das partes, nunca poderá exceder três meses; findo o prazo, o escrivão fará os autos conclusos ao juiz, que ordenará o prosseguimento do processo. II. Quando a sentença de mérito puder ser proferida senão depois de verificado determinado fato, ou de produzida certa prova, requisitada a outro juízo, o período de suspensão do processo nunca poderá exceder um ano. III. Extingue-se o processo, sem resolução de mérito quando ficar parado durante mais de um ano por negligência das partes. IV. Extingue-se o processo, sem resolução de mérito quando o autor desistir da ação; Depois de decorrido o prazo para a resposta, o autor não poderá, sem o consentimento do réu, desistir da ação. De acordo com o Código de Processo Civil, está correto o que se afirma em","o":["II, III e IV, apenas.","I, II e III, apenas.","I, II, III e IV.","III e IV, apenas.","I e II, apenas."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRE AP/TRE AP/Judiciária/2015 • TEC 315362","source":"FCC - AJ TRE AP/TRE AP/Judiciária/2015","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/315362","year":2015,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-315481","sourceQuestionId":"315481","t":"cpc-m10","moduleId":"cpc-m10","q":"O processo “A” foi suspenso porque a sentença de mérito depende do julgamento de outra causa; o processo “B” foi suspenso porque a sentença de mérito não pode ser proferida senão depois de produzida certa prova, requisitada a outro juízo. Nestes casos, de acordo com o Código de Processo Civil brasileiro,","o":["o período de suspensão não poderá exceder seis meses no processo “A” e um ano no processo “B”.","o período de suspensão não poderá exceder seis meses em ambos os processos.","o período de suspensão não poderá exceder um ano em ambos os processos.","o período de suspensão não poderá exceder um ano no processo “A” e seis meses no processo “B”.","não há previsão de um prazo limite para a suspensão de ambos os processos."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRE SE/TRE SE/Judiciária/2015 • TEC 315481","source":"FCC - AJ TRE SE/TRE SE/Judiciária/2015","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/315481","year":2015,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-326361","sourceQuestionId":"326361","t":"cpc-m10","moduleId":"cpc-m10","q":"No tocante à suspensão e à extinção do processo, é correto afirmar:","o":["O processo será extinto sem resolução do mérito, quando as partes transigirem, pois o acordo realizado impede seu exame.","Durante o prazo de suspensão do processo é defeso praticar qualquer ato processual, não podendo o juiz excepcionar essa regra geral.","A perda da capacidade processual da parte acarreta a suspensão do processo, visando à regularização do fato, mas sua morte extingue o processo.","A extinção do processo pelo acolhimento da alegação de coisa julgada dar-se-á com resolução de mérito, pois seu efeito é a imutabilidade do julgado anterior.","A suspensão do processo por convenção das partes nunca poderá exceder seis meses; findo esse prazo, o escrivão fará os autos conclusos ao juiz, que ordenará o prosseguimento do processo."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2015 • TEC 326361","source":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2015","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/326361","year":2015,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-173897","sourceQuestionId":"173897","t":"cpc-m10","moduleId":"cpc-m10","q":"Quando a sentença de mérito depender do julgamento de outra causa, ou da declaração da existência ou inexistência da relação jurídica, que constitua o objeto principal de outro processo pendente, o juiz determinará a","o":["suspensão do processo pelo prazo máximo de seis meses, não podendo ser praticado qualquer ato processual durante este período, exceto aqueles reputados urgentes.","extinção do processo sem resolução do mérito, devendo a ação ser reproposta quando a questão prejudicial for resolvida.","suspensão do processo, exceto se a audiência já tiver iniciado, caso em que o processo só será suspenso a partir da publicação da sentença.","extinção parcial do processo sem resolução do mérito, devendo prosseguir em relação às questões que não sofrem influência de outra causa.","suspensão do processo pelo prazo máximo de um ano."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT19/TRT 19/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 173897","source":"FCC - AJ TRT19/TRT 19/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/173897","year":2014,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-216912","sourceQuestionId":"216912","t":"cpc-m10","moduleId":"cpc-m10","q":"Quanto à formação, suspensão e extinção do processo, é correto afirmar:","o":["Durante a suspensão do processo pelos motivos previstos em lei é defeso praticar qualquer ato processual, sem exceção.","O processo civil começa e se desenvolve por iniciativa da parte, cabendo ao juiz supervisioná-lo para que atinja o seu desfecho com a prestação jurisdicional.","A morte ou perda da capacidade processual do autor conduz à extinção do processo, enquanto a morte ou perda da capacidade processual do réu leva à suspensão do processo para habilitação dos herdeiros.","Feita a citação, é defeso ao autor modificar o pedido ou a causa de pedir, sem a anuência do réu, mantendo- se as mesmas partes, salvo as substituições permitidas por lei.","A ocorrência da extinção do processo por litispendência ou coisa julgada dar-se-á com resolução do mérito."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PB/DPE PB/2014 • TEC 216912","source":"FCC - DP PB/DPE PB/2014","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/216912","year":2014,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3821948","sourceQuestionId":"3821948","t":"cpc-m10","moduleId":"cpc-m10","q":"No que concerne à petição inicial, em conformidade com o Código de Processo Civil,","o":["indeferida a petição inicial, o autor poderá apelar, facultado ao juiz, no prazo de 15 dias, retratar-se e, se não houver retratação, o juiz mandará citar o réu para responder ao recurso.","considera-se inepta a petição inicial, dentre outras situações, sempre que o pedido for indeterminado.","é lícita a cumulação, em um único processo, contra o mesmo réu, de vários pedidos, somente se entre eles houver conexão.","o autor poderá, até o saneamento do processo, aditar ou alterar o pedido e a causa de pedir, independentemente de consentimento do réu, assegurado o contraditório mediante a possibilidade de manifestação deste no prazo mínimo de 15 dias, facultado o requerimento de prova suplementar.","o pedido deve ser determinado, porém, é lícito formular pedido genérico, quando, dentre outras situações, a determinação do objeto ou do valor da condenação depender de ato que deva ser praticado pelo réu."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026 • TEC 3821948","source":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3821948","year":2026,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3451256","sourceQuestionId":"3451256","t":"cpc-m10","moduleId":"cpc-m10","q":"Considere o Código de Processo Civil brasileiro para responder à questão. A apelação interposta contra o indeferimento da inicial gerará a citação do réu para","o":["apresentar contestação e responder o recurso, concomitantemente.","apresentar contestação.","apenas tomar ciência do processo sem possibilidade de manifestação.","manifestar-se acerca de eventual juízo de retratação, apenas.","responder o recurso."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3451256","source":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3451256","year":2025,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3571728","sourceQuestionId":"3571728","t":"cpc-m10","moduleId":"cpc-m10","q":"Ao verificar que a petição inicial não preenchia os requisitos legais, o juiz proferiu decisão determinando ao autor que promovesse a sua emenda no prazo de 05 dias, sob pena de indeferimento. Dessa decisão, o autor foi intimado somente pela imprensa, na pessoa do seu advogado, mas não promoveu a emenda no prazo determinado pelo juiz. Em razão disso, o juiz indeferiu a petição inicial e extinguiu o processo, mesmo sem determinar a intimação pessoal do autor para correção do vício da petição inicial. Nesse caso, de acordo com o Código de Processo Civil, o juiz agiu","o":["corretamente, porque, não sendo corrigido o vício da petição inicial no prazo de 05 dias, impunha-se o seu indeferimento, independentemente de intimação pessoal do autor para promover a emenda.","incorretamente, porque o prazo para emenda da petição inicial não poderá ser fixado em menos de 10 dias; além disso, decorrido o prazo sem a correção dos vícios da petição inicial, caberia ao juiz ter concedido ao autor uma nova oportunidade de promover a emenda antes de extinguir o processo.","incorretamente, porque a petição inicial não poderia ter sido indeferida sem que antes o autor tivesse sido pessoalmente intimado a promover a emenda, sendo insuficiente para tanto a mera intimação na pessoa do seu advogado; no entanto, o prazo estipulado pelo juiz para realização a emenda está correto, já que a lei determina que ele poderá ser fixado entre 05 e 15 dias.","incorretamente, porque o prazo legal para que o autor apresente emenda à petição inicial é de 15 dias; além disso, a petição inicial não poderia ter sido indeferida sem que antes o autor fosse pessoalmente intimado a promover a emenda, sendo insuficiente para tanto a mera intimação na pessoa do seu advogado.","incorretamente, porque o prazo legal para que o autor apresente emenda à petição inicial é de 15 dias, embora seja desnecessária a sua intimação pessoal para o ato, bastando que ela seja feita na pessoa do seu advogado."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2025 • TEC 3571728","source":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3571728","year":2025,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2874538","sourceQuestionId":"2874538","t":"cpc-m10","moduleId":"cpc-m10","q":"Suzane ajuizou demanda indenizatória, porém teve sua petição inicial indeferida, em razão de inépcia desta. Nessa situação, se Suzane interpuser apelação,","o":["o recurso deverá ser indeferido, já que o CPC prevê expressamente o cabimento de agravo de instrumento para essa hipótese.","o réu deve ser intimado para tomar ciência do processo, sem, contudo, poder apresentar contrarrazões ao recurso.","os autos serão remetidos ao tribunal sem a citação da parte requerida.","o juiz poderá retratar-se no prazo de cinco dias.","no caso de reforma da sentença pelo tribunal, o prazo para contestação será iniciado a partir da publicação do acórdão no diário oficial."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT11/TRT 11/Judiciária/\"Sem Especialidade\"/2024 • TEC 2874538","source":"FCC - AJ TRT11/TRT 11/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2874538","year":2024,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3023458","sourceQuestionId":"3023458","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, se a petição inicial apresentar defeitos e irregularidades capazes de dificultar o julgamento de mérito, o juiz","o":["determinará que o autor a emende ou a complete, no prazo de 15 dias, indicando com precisão o que deve ser corrigido ou completado, sob pena de indeferimento da petição inicial, com extinção do processo com resolução de mérito.","determinará que o autor a emende ou a complete, no prazo de 5 dias, indicando com precisão o que deve ser corrigido ou completado, sob pena de indeferimento da petição inicial, com extinção do processo com resolução de mérito.","a Indeferirá de plano, extinguindo o processo com resolução de mérito.","determinará que o autor a emende ou a complete, no prazo de 15 dias, indicando com precisão o que deve ser corrigido ou completado, sob pena de indeferimento da petição inicial, com extinção do processo sem resolução de mérito.","a indeferirá de plano, extinguindo o processo sem resolução de mérito."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2024 • TEC 3023458","source":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3023458","year":2024,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126620","sourceQuestionId":"3126620","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, em ação que tenha por objeto o cumprimento de obrigação em prestações sucessivas.","o":["o autor deve requerer expressamente a condenação do réu ao pagamento das prestações vincendas, ao contrário do que se a com os juros legais, com a correção monetária e com as verbas de sucumbência, os quais estão compreendidos no principal.","o autor deve requerer expressamente a condenação do réu ao pagamento das prestações vincendas, dos juros legai, da correção monetária e das verbais de sucumbência, sob pena de preclusão.","as prestações vincendas estão incluídas no pedido, independentemente de declaração expressa do autor, assim como no principal se compreendem os juros legais, a correção monetária e as verbas de sucumbência.","as prestações não vencidas quando do ajuizamento da ação devem ser objeto de ação autônoma, tendo em vista não se admitir pedido incerto.","as prestações vincendas estão incluídas no pedido, independentemente de declaração expressa do autor, ao contrário do que se dá com os juros legais, com a correção monetária e com as verbas de sucumbência, os quais devem ser objeto de pedido expresso, sob pena de preclusão."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126620","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126620","year":2024,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2740952","sourceQuestionId":"2740952","t":"cpc-m10","moduleId":"cpc-m10","q":"Considerando que a petição inicial continha o pedido condenatório ao pagamento do valor de R$ 20.000,00, sem fazer qualquer pedido expresso quanto à incidência de juros, correção monetária, verbas sucumbenciais e honorários advocatícios, de acordo com as disposições do CPC/2015 e o valor do pedido realizado pelo autor na petição inicial, a sentença:","o":["não poderá ultrapassar o valor nominal constante do pedido do autor na petição inicial, em observância ao princípio da correlação e da adstrição, sob pena de nulidade da sentença, por se tratar de julgamento citra petita.","não poderá ultrapassar o valor nominal constante do pedido do autor na petição inicial, em observância ao princípio da correlação e da adstrição, sob pena de nulidade da sentença, por se tratar de julgamento ultra petita.","pode condenar o réu ao pagamento de valor nominal superior ao pedido, pois a incidência de juros, legais e contratuais, correção monetária e verbas sucumbenciais, com exceção de honorários advocatícios, prescinde da realização de pedido expresso.","não poderá ultrapassar o valor nominal constante do pedido do autor na petição inicial, em observância ao princípio da correlação e da adstrição, sob pena de nulidade da sentença, por se tratar de julgamento extra petita.","pode condenar o réu ao pagamento de valor nominal superior ao pedido, pois a incidência de juros legais, correção monetária e verbas sucumbenciais, inclusive honorários advocatícios, prescinde da realização de pedido expresso."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP ES/DPE ES/2023 • TEC 2740952","source":"FCC - DP ES/DPE ES/2023","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2740952","year":2023,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021310","sourceQuestionId":"2021310","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, a petição inicial será indeferida se","o":["depois de intimado a emendá-la o autor não cumprir a diligência determinada pelo Juiz.","não indicar o endereço do réu, ainda que seja possível citá-lo.","tiver sido distribuída a juízo relativamente incompetente.","tiver sido distribuída a juízo absolutamente incompetente.","o autor demandar quantia ilíquida."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Proc (PGE AM)/PGE AM/2022 • TEC 2021310","source":"FCC - Ana Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021310","year":2022,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2032372","sourceQuestionId":"2032372","t":"cpc-m10","moduleId":"cpc-m10","q":"Em determinada ação judicial, o autor requer o pagamento de aluguéis de coisa móvel vencidos e não pagos. Levando-se em conta que, segundo o Código de Processo Civil, o pedido deve ser certo e determinado:","o":["Em atenção ao princípio da inércia da jurisdição, os aluguéis vencidos ao longo da ação não poderão ser incluídos na condenação, devendo ser objeto de ação própria.","Consideram-se incluídos no pedido principal os juros legais, a correção monetária, o dano moral e a multa contratual.","Em respeito ao princípio da correlação ou congruência, apenas mediante pedido expresso na petição inicial os aluguéis vencidos ao longo da ação e não pagos pelo réu poderão ser incluídos na condenação.","Como o pedido delimita a atividade jurisdicional, não é possível considerar incluída nenhuma prestação que não tenha sido expressamente mencionada pelo autor na petição inicial, excetuando-se, apenas, as verbas de sucumbência.","Tratando-se no caso de obrigação em prestações sucessivas, os aluguéis vencidos no curso do processo, não pagos ou consignados pelo réu, enquanto durar a obrigação, serão considerados incluídos no pedido, independentemente de pedido expresso do autor, e poderão ser incluídos na condenação."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (UNICAMP)/UNICAMP/2022 • TEC 2032372","source":"FCC - Proc (UNICAMP)/UNICAMP/2022","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2032372","year":2022,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2454187","sourceQuestionId":"2454187","t":"cpc-m10","moduleId":"cpc-m10","q":"O pedido é elencado pelo Código de Processo Civil como requisito fundamental da petição inicial. Em relação ao tema,","o":["é vedada a cumulação de vários pedidos em um único processo contra a mesma parte ré.","os pedidos serão interpretados restritivamente, compreendendo-se, no principal, os juros legais.","nas ações com cumprimento de obrigação em prestações sucessivas, essas serão consideradas incluídas no pedido, independentemente de declaração expressa da parte autora.","o pedido será subsidiário quando, pela natureza da obrigação, a parte devedora puder cumprir a prestação de mais de um modo.","após a citação, a parte autora poderá alterar o pedido independentemente de consentimento da parte ré."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2022 • TEC 2454187","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2022","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2454187","year":2022,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1736855","sourceQuestionId":"1736855","t":"cpc-m10","moduleId":"cpc-m10","q":"Mévio vendeu um carro a Tício, que se obrigou a pagá-lo em vinte e quatro prestações mensais sucessivas. No quarto mês, porém, Tício caiu em inadimplência, razão pela qual Mévio ajuizou ação de cobrança do débito vencido, a qual foi julgada procedente. Na sentença, o juiz, além dos consectários compreendidos no pedido, deverá condenar Tício ao pagamento","o":["apenas do débito vencido, pois é vedado ao juiz proferir sentença genérica.","apenas do débito vencido, sob pena de a sentença ser considerada extra petita.","do débito vencido e das prestações que se vencerem até a citação, ainda que Mévio não as tenha pedido expressamente, se, no curso do processo, não forem pagas nem consignadas.","apenas do débito vencido, sobre pena de a sentença ser considerada ultra petita.","do débito vencido e das prestações vincendas, enquanto durar a obrigação, ainda que Mévio não as tenha pedido expressamente, se, no curso do processo, não forem pagas nem consignadas."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJGO/TJ GO/2021 • TEC 1736855","source":"FCC - JE TJGO/TJ GO/2021","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1736855","year":2021,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1752324","sourceQuestionId":"1752324","t":"cpc-m10","moduleId":"cpc-m10","q":"Em relação ao pedido,","o":["é possível a alteração do pedido até o saneamento do processo, sem o consentimento do réu, desde que assegurado o contraditório mediante a possibilidade de manifestação no prazo de 15 dias e produção de prova suplementar.","são cumuláveis os pedidos de procedimentos processuais diversos, desde que adotado o procedimento comum e que o autor abra mão do emprego de técnicas processuais diferenciadas previstas nos procedimentos especiais.","são cumuláveis os pedidos ainda que o juízo não seja competente para um dos pedidos, observando-se o princípio da efetividade.","são cumuláveis os pedidos de procedimentos processuais diversos, desde que adotado o procedimento comum, sem prejuízo do emprego de técnicas processuais diferenciadas previstas nos procedimentos especiais que não forem incompatíveis com o procedimento comum.","o pedido subsidiário é aquele em que é facultado ao juiz que acolha qualquer um dos pedidos formulados sem ordem de preferência."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP GO/DPE GO/2021 • TEC 1752324","source":"FCC - DP GO/DPE GO/2021","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1752324","year":2021,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1147300","sourceQuestionId":"1147300","t":"cpc-m10","moduleId":"cpc-m10","q":"Indeferida a inicial, o autor","o":["poderá apelar, facultado ao juiz, no prazo de cinco dias, retratar-se; se não houver retratação, o juiz mandará citar o réu para responder ao recurso.","poderá apelar, subindo os autos ao Tribunal imediatamente, sem citação do réu para resposta ao recurso.","poderá impetrar mandado de segurança, pelo direito líquido e certo à prestação jurisdicional.","deverá aguardar o trânsito em julgado, se quiser ajuizar nova demanda sobre a mesma matéria, não sendo possível o juízo de retratação.","poderá apelar, com possibilidade de retratação do juiz em cinco dias; não havendo retratação, os autos subirão imediatamente, não havendo citação do réu porque não chegou a se constituir a relação jurídico-processual."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJMS/TJ MS/2020 • TEC 1147300","source":"FCC - JE TJMS/TJ MS/2020","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1147300","year":2020,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-789022","sourceQuestionId":"789022","t":"cpc-m10","moduleId":"cpc-m10","q":"O pedido deve ser certo e determinado. No entanto,","o":["são compreendidos no principal os juros legais, a correção monetária e as verbas de sucumbência, inclusive os honorários advocatícios.","considera-se implícito o requerimento de multa, mesmo que não tenha sido prevista contratualmente.","na demanda que tenha por objeto o cumprimento de prestações sucessivas, essas serão consideradas incluídas no pedido, desde que haja pedido de declaração expresso do autor nesse sentido.","somente na hipótese de ações universais, se o autor não puder individuar os bens demandados, o pedido poderá ser genérico.","é lícita a cumulação, em um único processo, de vários pedidos contra o mesmo réu, desde que haja conexão ou continência entre eles."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019 • TEC 789022","source":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/789022","year":2019,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1005246","sourceQuestionId":"1005246","t":"cpc-m10","moduleId":"cpc-m10","q":"Se a petição inicial não preencher os requisitos legais, apresentando defeitos e irregularidades capazes de dificultar o julgamento de mérito e verificando-se ainda a incapacidade processual da parte, deverá o juiz,","o":["em ambas as situações, extinguir desde logo o processo, pois o atual sistema processual civil não admite vícios em relação à petição inicial nem convalida a incapacidade processual verificada no início da demanda.","em ambas situações, suspender o processo e designar prazo razoável para que sejam sanados os vícios.","quanto aos defeitos e irregularidades capazes de dificultar o julgamento do mérito, determinar que o autor emende a inicial ou a complete em quinze dias, indicando com precisão o que deve ser corrigido ou completado; quanto à incapacidade processual verificada, o juiz suspenderá o processo e designará prazo razoável para que seja sanado o vício.","em ambas as situações, sem suspender o processo, determinar a emenda à inicial e o suprimento do vício processual no prazo de quinze dias.","determinar a emenda à inicial em quinze dias quanto aos defeitos e irregularidades verificados, extinguindo desde logo o processo no tocante à incapacidade processual verificada, por se tratar de vício que não admite convalidação."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Prom Jus (MPE MT)/MPE MT/2019 • TEC 1005246","source":"FCC - Prom Jus (MPE MT)/MPE MT/2019","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1005246","year":2019,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1037217","sourceQuestionId":"1037217","t":"cpc-m10","moduleId":"cpc-m10","q":"Considere os enunciados seguintes, referentes à petição inicial: I. Na ação que tiver por objeto cumprimento de obrigação em prestações sucessivas, essas serão consideradas incluídas no pedido, independentemente de declaração expressa do autor, e serão incluídas na condenação, enquanto durar a obrigação, se o devedor, no curso do processo, deixar de pagá-las ou de consigná-las. II. O pedido deve ser determinado, sendo lícito porém formular pedido genérico somente se não for possível determinar, desde logo, as consequências do ato ou do fato, ou ainda, nas ações universais, se o autor não puder individuar os bens demandados. III. É lícita a cumulação em um único processo, contra o mesmo réu, de vários pedidos, desde que entre eles haja conexão ou continência. IV. Na obrigação indivisível com pluralidade de credores, aquele que não participou do processo receberá sua parte, deduzidas as despesas na proporção de seu crédito. Está correto o que se afirma APENAS em","o":["II e III.","II e IV.","I, II e III.","I e IV.","I, III e IV."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJAL/TJ AL/2019 • TEC 1037217","source":"FCC - JE TJAL/TJ AL/2019","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1037217","year":2019,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592918","sourceQuestionId":"592918","t":"cpc-m10","moduleId":"cpc-m10","q":"Em relação à petição inicial e ao pedido, está correto afirmar:","o":["Se o juiz verificar que a petição inicial não preenche os requisitos legais ou que apresenta defeitos e irregularidades capazes de dificultar o julgamento de mérito, determinará que o autor, no prazo de quinze dias, a emende ou a complete, indicando com precisão o que deve ser corrigido ou complementado.","O pedido deve ser certo, mas são compreendidos no principal os juros legais, a multa contratual, a correção monetária e as verbas de sucumbência, inclusive honorários advocatícios.","O pedido deve ser determinado, inexistindo na atual sistemática processual civil a possibilidade de formulação de pedidos genéricos, salvo somente nas ações universais, se o autor não puder individuar os bens demandados.","É lícita a cumulação, em um único processo, de vários pedidos contra o mesmo réu, ainda que entre eles não haja conexão, somente se os pedidos forem compatíveis entre si e se o tipo de procedimento for o mesmo.","O pedido poderá ser alterado pelo autor até a citação, bem como a causa de pedir, desde que haja a anuência do réu"],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2018 • TEC 592918","source":"FCC - Proc (PGE TO)/PGE TO/2018","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592918","year":2018,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-605411","sourceQuestionId":"605411","t":"cpc-m10","moduleId":"cpc-m10","q":"O recurso adequado para a impugnação de decisão que indefere a petição inicial, sob o fundamento de inépcia, é o de","o":["agravo de instrumento, sendo facultado ao juiz, no prazo de cinco dias, retratar-se.","apelação, inexistindo previsão legal de retratação por parte do magistrado.","apelação, sendo facultado ao juiz, no prazo de cinco dias, retratar-se.","agravo de instrumento, inexistindo previsão legal de retratação por parte do magistrado.","apelação, sendo facultado ao juiz, após a citação do réu para responder ao recurso, retratar-se no prazo de dez dias."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2018 • TEC 605411","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2018","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/605411","year":2018,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-677636","sourceQuestionId":"677636","t":"cpc-m10","moduleId":"cpc-m10","q":"Quanto à petição inicial e ao pedido,","o":["o autor poderá, até o saneamento do processo, aditar ou alterar o pedido ou a causa de pedir, sem consentimento do réu, assegurado o contraditório.","o juiz poderá julgar liminarmente improcedente o pedido se verificar, desde logo, a ocorrência de decadência ou de prescrição, ou se considerar a parte como manifestamente ilegítima.","indeferida a petição inicial, o autor poderá apelar, facultado ao juiz, no prazo de quinze dias, retratar-se; não havendo a retratação, o juiz mandará citar o réu para responder ao recurso.","na ação que tiver por objeto cumprimento de obrigação em prestações sucessivas, essas serão consideradas incluídas no pedido, independentemente de declaração expressa do autor, e serão incluídas na condenação, enquanto durar a obrigação, se o devedor, no curso do processo, deixar de pagá-las ou de consigná- las.","é lícita a cumulação, em um único processo, contra o mesmo réu, de vários pedidos, desde que haja conexão entre eles."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE AP)/PGE AP/2018 • TEC 677636","source":"FCC - Proc (PGE AP)/PGE AP/2018","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/677636","year":2018,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-733916","sourceQuestionId":"733916","t":"cpc-m10","moduleId":"cpc-m10","q":"Em regra, ao formular a petição inicial, caberá ao autor deduzir pedido determinado. Admite-se, porém, a formulação de pedido genérico, entre outras hipóteses,","o":["quando não for possível determinar, desde logo, as consequências do ato ou do fato.","nas ações universais, mesmo se o autor puder individuar os bens demandados.","quando a determinação do objeto, das partes ou do valor da condenação depender de ato de terceiro.","quando a parte autora for hipossuficiente em relação ao réu.","quando desconhecido o réu, nas ações fundadas em direito real."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Tec Min (MPE PE)/MPE PE/Administrativa/2018 • TEC 733916","source":"FCC - Tec Min (MPE PE)/MPE PE/Administrativa/2018","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/733916","year":2018,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-455578","sourceQuestionId":"455578","t":"cpc-m10","moduleId":"cpc-m10","q":"José ajuizou procedimento comum, mas a petição inicial foi indeferida por conter pedidos incompatíveis entre si. Nesse caso, dessa decisão","o":["caberá agravo de instrumento.","caberá apelação.","caberá agravo interno.","caberá recurso especial.","não caberá recurso."],"a":1,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT11/TRT 11/Judiciária/Oficial de Justiça Avaliador Federal/2017 • TEC 455578","source":"FCC - AJ TRT11/TRT 11/Judiciária/Oficial de Justiça Avaliador Federal/2017","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/455578","year":2017,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-460657","sourceQuestionId":"460657","t":"cpc-m10","moduleId":"cpc-m10","q":"É requisito da petição inicial a formulação de pedido, com suas especificações. De acordo com o novo Código de Processo Civil,","o":["na ação que visar ao cumprimento de obrigação em prestações sucessivas, essas só serão consideradas incluídas no pedido mediante declaração expressa do autor.","é permitida a formulação de pedido genérico em reconvenção nas mesmas hipóteses em que seria cabível em ação principal.","o pedido poderá ser aditado até a citação, desde que haja consentimento do réu.","é lícita a cumulação, em um único processo, contra o mesmo réu, de vários pedidos, desde que entre eles haja conexão.","é vedada a cumulação de pedidos se para cada um deles corresponder tipo diverso de procedimento, ainda que o autor empregue o procedimento comum."],"a":1,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRE SP/TRE SP/Administrativa/\"Sem Especialidade\"/2017 • TEC 460657","source":"FCC - AJ TRE SP/TRE SP/Administrativa/\"Sem Especialidade\"/2017","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/460657","year":2017,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-583800","sourceQuestionId":"583800","t":"cpc-m10","moduleId":"cpc-m10","q":"Atenção: Considere o novo Código de Processo Civil para responder à questão. Ao receber ação de consignação em pagamento formulada por Pedro contra André, o juiz indeferiu a petição inicial, por entender ausente o interesse de agir. Nesse caso, Pedro poderá interpor","o":["apelação, sendo facultado ao juiz, no prazo de 5 dias, retratar-se da sentença; se não houver retratação, o juiz mandará citar André para responder ao recurso, para só então determinar a remessa do feito ao Tribunal.","agravo, sendo facultado ao juiz, no prazo de 5 dias, retratar-se da decisão; se não houver retratação, o juiz mandará citar André para responder ao recurso, para só então determinar a remessa do feito ao Tribunal.","apelação, caso em que o juiz deverá, independentemente de juízo de admissibilidade, determinar a imediata remessa do feito ao Tribunal, sem possibilidade de retratação, pois com a prolação da sentença se encerra a jurisdição de primeiro grau.","agravo, caso em que o juiz deverá, independentemente de juízo de admissibilidade, determinar a imediata remessa do feito ao Tribunal, sem possibilidade de retratação, pois com a prolação da sentença se encerra a jurisdição de primeiro grau.","interpor apelação, sendo facultado ao juiz, no prazo de 5 dias, retratar-se da sentença; se não houver retratação, o juiz deverá, independentemente de juízo de admissibilidade, determinar a imediata remessa do feito ao Tribunal, sem ordenar a citação do réu."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF5/TRF 5/Judiciária/Oficial de Justiça Avaliador Federal/2017 • TEC 583800","source":"FCC - AJ TRF5/TRF 5/Judiciária/Oficial de Justiça Avaliador Federal/2017","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/583800","year":2017,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-337493","sourceQuestionId":"337493","t":"cpc-m10","moduleId":"cpc-m10","q":"Mário ajuizou ação de indenização por danos materiais contra José. Depois de distribuída a ação, requereu o aditamento da petição inicial para formular pedido de compensação por danos morais. De acordo com o Código de Processo Civil, a alteração do pedido ou da causa de pedir","o":["depende do consentimento do réu, se já tiver sido feita a citação, e não poderá ocorrer após o saneamento do processo.","é defesa antes da citação.","sempre depende do consentimento do réu.","pode ocorrer a qualquer tempo, inclusive após o saneamento do processo, desde que haja consentimento do réu.","pode ocorrer a qualquer tempo, inclusive após o saneamento do processo, independentemente de consentimento do réu."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (São Luís)/Pref São Luís/2016 • TEC 337493","source":"FCC - Proc (São Luís)/Pref São Luís/2016","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/337493","year":2016,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-362381","sourceQuestionId":"362381","t":"cpc-m10","moduleId":"cpc-m10","q":"Na atual sistemática processual civil, no tocante ao pedido é correto afirmar:","o":["Na obrigação indivisível com pluralidade de credores, somente quem participou do processo receberá sua parte, por se tratar de litisconsórcio necessário, cabendo a quem não interveio propor ação autônoma de cobrança.","Podem ser cumulados vários pedidos, em um único processo, contra o mesmo réu, desde que entre eles haja conexão, sejam os pedidos compatíveis entre si, o mesmo juízo seja competente para conhecer deles e o tipo de procedimento seja adequado para todos os pedidos formulados.","Será alternativo quando, pela natureza da obrigação, o devedor puder cumprir a prestação de mais de um modo; se a escolha couber ao devedor, pela lei ou pelo contrato, o juiz lhe assegurará o direito de cumprir a prestação de um ou de outro modo, ainda que o autor não tenha formulado pedido alternativo.","Até o saneamento do processo, o pedido poderá ser aditado ou alterado, bem como a causa de pedir, ainda que sem o consentimento do réu, ao qual, porém, será devolvido o prazo para oferecimento de contestação quanto aos novos fatos e argumentos de direito apresentados nos autos.","Quando diga respeito a prestações sucessivas, essas serão consideradas incluídas no pedido, independentemente de declaração expressa do autor, sendo incluídas na condenação até sentença, como termo final, se o devedor deixou de pagá-las ou de consigná-las no curso do processo."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (Pref Campinas)/Pref Campinas/2016 • TEC 362381","source":"FCC - Proc (Pref Campinas)/Pref Campinas/2016","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/362381","year":2016,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-257050","sourceQuestionId":"257050","t":"cpc-m10","moduleId":"cpc-m10","q":"No tocante às condições da ação e aos pressupostos processuais,","o":["para que o juiz possa examinar o pedido inicial deve examinar preliminarmente tanto as condições da ação como os pressupostos processuais, ambos antecedendo a análise da pretensão meritória do autor.","a análise do mérito depende da prévia perquirição dos pressupostos processuais, mas não das condições da ação, que já dizem respeito ao próprio mérito da pretensão deduzida em juízo.","o exame do mérito depende da prévia análise das condições da ação, mas não dos pressupostos processuais, que se consideram como prejudiciais do mérito deduzido em juízo.","tanto os pressupostos processuais como as condições da ação são prejudiciais à análise do mérito e, reconhecida sua ausência, implica deva o juiz determinar a emenda da petição inicial, para sanar o vício.","embora preliminares à pretensão meritória, o reconhecimento da ausência das condições da ação ou dos pressupostos processuais conduz à extinção do processo com resolução do mérito, obstando a que, em regra, seja a demanda ajuizada novamente."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - ACE (TCM-GO)/TCM GO/Jurídica/2015 • TEC 257050","source":"FCC - ACE (TCM-GO)/TCM GO/Jurídica/2015","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/257050","year":2015,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-300756","sourceQuestionId":"300756","t":"cpc-m10","moduleId":"cpc-m10","q":"João e Pedro celebraram contrato por meio do qual João se comprometeu a pagar a Pedro, pelo prazo de dois anos, a quantia mensal de R$ 2.000,00. Passado algum tempo, João parou de pagar, passando a ser devedor de três prestações. Ainda faltando mais de um ano para a conclusão do contrato, Pedro ajuizou ação cobrando as prestações em atraso. No pedido, Pedro não fez referência às prestações vincendas, tampouco aos juros legais. No curso do processo, João não pagou as prestações. Convencido de que a pretensão procede, o Juiz deverá condenar João a pagar a Pedro","o":["apenas as prestações vencidas, sem acréscimo dos juros legais.","as prestações vencidas e vincendas, acrescidas dos juros legais.","apenas as prestações vencidas, sem acréscimo dos juros legais, salvo se, até a citação, Pedro aditar o pedido para nele incluir as prestações vencidas e os juros legais.","apenas as prestações vencidas, com acréscimo dos juros legais.","as prestações vencidas e vincendas, sem acréscimo dos juros legais."],"a":1,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT15/TRT 15/2015 • TEC 300756","source":"FCC - JT TRT15/TRT 15/2015","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/300756","year":2015,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-326358","sourceQuestionId":"326358","t":"cpc-m10","moduleId":"cpc-m10","q":"A cumulação de pedidos,","o":["é admitida, mesmo que cada pedido corresponda a um tipo diverso de procedimento, se o autor empregar o procedimento ordinário.","é sempre possível, independentemente do procedimento adotado, por configurar hipótese de economia e agilidade processuais.","não é possível, porque cada um deles exige rito próprio e singular, sem possibilidade de adaptação processual.","é possível, como regra geral, contra o mesmo réu, em um único processo, desde que entre eles haja conexão, necessariamente.","é possível desde que todos eles exijam o rito ordinário, pois tipos diferentes de procedimento impedem a cumulação, por incompatibilidade lógica."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2015 • TEC 326358","source":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2015","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/326358","year":2015,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-373380","sourceQuestionId":"373380","t":"cpc-m10","moduleId":"cpc-m10","q":"Uma vez apresentada a petição inicial,","o":["não há possibilidade legal de aditamento do pedido, salvo se houver anuência do réu após sua citação.","quando a matéria controvertida for só de direito, mas no juízo já houver sido proferida sentença de parcial ou de total improcedência em outros casos idênticos, poderá ser dispensada a citação e proferida sentença, reproduzindo-se o teor da anteriormente prolatada.","nos litígios que tenham por objeto obrigações decorrentes de empréstimo, financiamento ou arrendamento mercantil, o autor deverá discriminar na peça inicial, dentre as obrigações contratuais, aquelas que pretende controverter, quantificando o valor incontroverso.","o juiz poderá, diante do não preenchimento na peça inicial de todos os requisitos legais, ou determinar sua emenda, ou indeferi-la de pronto, por inépcia, ainda que a emenda fosse possível.","o pedido nela contido deve ser necessariamente certo ou determinado, porque é defeso oferecer pedido condicional ou abstrato."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJPI/TJ PI/2015 • TEC 373380","source":"FCC - JE TJPI/TJ PI/2015","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373380","year":2015,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-177948","sourceQuestionId":"177948","t":"cpc-m10","moduleId":"cpc-m10","q":"Fábio ajuizou ação contra Marcelo em razão de ato ilícito. Alegou Fábio, na petição inicial, que Marcelo lhe desferiu um soco no abdome, causando danos materiais consistentes em lucros cessantes. Citado, Marcelo apresentou contestação. Ato contínuo, o feito foi saneado. Depois deste ato, porém, Fábio requereu o aditamento da petição inicial para dois fins: primeiro, mencionar, na causa de pedir, que o golpe se deu na presença de várias pessoas; segundo, postular, além da indenização pelos danos materiais, compensação por danos morais. Intimado a se manifestar, Marcelo aceitou o pedido de emenda. Neste caso, o juiz deverá","o":["indeferir em parte o pedido de emenda da petição inicial, pois, depois do saneamento do processo, a lei veda a alteração da causa de pedir, mas não do pedido.","deferir o pedido de emenda da petição inicial, abrindo oportunidade para nova contestação de Marcelo, sob pena de ofensa ao princípio do contraditório.","indeferir o pedido de emenda da petição inicial, pois, depois do saneamento do processo, a lei veda a alteração do pedido e da causa de pedir, mesmo que tenha havido concordância da parte contrária.","deferir o pedido de emenda da petição inicial, mas sem abrir oportunidade para nova contestação de Marcelo, tendo em vista que tal manifestação já poderia ter sido feita quando intimado a se manifestar sobre o pedido formulado por Fábio.","indeferir em parte o pedido de emenda da petição inicial, pois, depois do saneamento do processo, a lei veda a alteração do pedido, mas não da causa de pedir."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc Jud (Pref Recife)/Pref Recife/2014 • TEC 177948","source":"FCC - Proc Jud (Pref Recife)/Pref Recife/2014","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/177948","year":2014,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-227310","sourceQuestionId":"227310","t":"cpc-m10","moduleId":"cpc-m10","q":"Sobre a causa de pedir, é correto afirmar:","o":["Traduzida no fato e nos fundamentos jurídicos do pedido, além de expresso requisito da petição inicial, é um dos elementos identificadores da demanda, com repercussão direta no alcance da coisa julgada.","O CPC adotou a teoria da substanciação, exigindo que se apresente o fato, os fundamentos jurídicos (relação jurídica) e o pedido.","O CPC, ao dispor que a causa de pedir deve individualizar os fatos e os fundamentos jurídicos do pedido, adotou a teoria da individuação.","Conforme preceituado pelo CPC, contém o fato e os fundamentos jurídicos do pedido, esses sinônimos de fundamento legal.","O fundamento legal invocado na petição inicial e a argumentação utilizada integram a causa de pedir, a qual, juntamente com o pedido, delimita os contornos objetivos da lide, repercutindo no futuro alcance da coisa julgada material."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2014 • TEC 227310","source":"FCC - DP RS/DPE RS/2014","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/227310","year":2014,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-254792","sourceQuestionId":"254792","t":"cpc-m10","moduleId":"cpc-m10","q":"Em razão de acidente, Cristiano sofreu danos físicos e estéticos, além de danos materiais emergentes, consistentes nas despesas hospitalares, e lucros cessantes. Por tal razão, ajuizou ação contra o causador do dano requerendo indenização pelos danos materiais emergentes, não mencionando a incidência de juros legais sobre o principal. De acordo com o Código de Processo Civil, se julgar procedente o pedido, o Juiz deverá condenar o réu a indenizar Cristiano por danos materiais emergentes","o":["e juros legais, tendo em vista que os pedidos são interpretados restritivamente, mas compreendendo no principal os juros legais.","sem incidência de juros legais, tendo em vista que os pedidos são interpretados restritivamente, não compreendendo tal consectário da condenação.","mais lucros cessantes, por possuírem a mesma natureza dos danos materiais emergentes, porém sem incidência de juros legais, tendo em vista que os pedidos são interpretados restritivamente, não compreendendo tal consectário da condenação.","mais lucros cessantes, danos morais e estéticos, além de juros legais, tendo em vista que os pedidos são interpretados ampliativamente, de modo que a sentença atenda à real intenção do autor.","mais lucros cessantes, por possuírem a mesma natureza dos danos materiais emergentes, além de juros legais, os quais estão compreendidos no principal."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT1/TRT 1/2014 • TEC 254792","source":"FCC - JT TRT1/TRT 1/2014","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/254792","year":2014,"caderno":3,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3853435","sourceQuestionId":"3853435","t":"cpc-m11","moduleId":"cpc-m11","q":"Na contestação, incumbe ao réu alegar matérias preliminares antes de discutir o mérito. Considere: I. prescrição. II. coisa julgada. III. incompetência relativa. IV. decadência. São matérias preliminares, o que consta APENAS de","o":["I, II e IV.","II e IV.","I, III e IV.","II e III.","I e III."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026 • TEC 3853435","source":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3853435","year":2026,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3670671","sourceQuestionId":"3670671","t":"cpc-m11","moduleId":"cpc-m11","q":"A respeito dos honorários advocatícios sucumbenciais, é correto afirmar:","o":["Serão fixados por apreciação equitativa quando inestimável, irrisório ou excessivo o proveito econômico da demanda.","Quando fixados contra a Fazenda Pública, não poderão ser executados por meio de requisição de pequeno valor (RPV) se o crédito principal só puder ser exigido por meio de precatório.","Se o autor optar por realizar a substituição do réu, diante da alegação de ilegitimidade ad causam formulada em contestação, pagará honorários sucumbenciais, que serão fixados entre 3 e 5 por cento do valor da causa, desde que não irrisório.","A desistência da ação, se for total, enseja a fixação de honorários sucumbenciais a serem pagos pelo autor, mas, se for parcial, não incidem os honorários.","Se não houver requerimento de sua fixação na petição inicial, somente por ação autônoma poderá o advogado pleiteá-los."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670671","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670671","year":2025,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3228697","sourceQuestionId":"3228697","t":"cpc-m11","moduleId":"cpc-m11","q":"Em ação movida por Paulo contra Maria, esta apresentou contestação alegando, em preliminar, não ser parte legitima. Alegou, ainda, que a ação devia ter sido proposta contra Fernanda, única legitimada a figurar no polo passivo. Intimado a se manifestar sobre a contestação, Paulo concordou com a preliminar, pleiteando a substituição de Maria por Fernanda, com o prosseguimento do feito. Nesse caso, de acordo com o Código de Processo Civil, verificando a procedência da preliminar, o juiz deverá","o":["deferir a substituição da ré, sem extinguir o processo, além disso, deverá condenar Paulo a reembolsar as despesas suportadas por Maria, bem como a pagar honorários em favor do advogado dela.","extinguir o processo e indeferir a substituição da ré, porquanto inadmissível depois da contestação, além disso, deverá condenar Paulo a reembolsar as despesas suportadas por Maria, mas não o condenará ao pagamento de honorários em favor do advogado dela.","deferir a substituição da ré, sem extinguir o processo, além disso, deverá condenar Paulo a reembolsar as despesas suportadas por Maria, mas não o condenará ao pagamento de honorários em favor do advogado dela.","deferir a substituição da ré, sem extinguir o processo; contudo, não deverá condenar Paulo a reembolsar as despesas suportadas por Maria ou a pagar honorários em favor do advogado dela, salvo se identificar ma -fé.","extinguir o processo e indeferir a substituição da ré, porquanto inadmissível depois da contestação; além disso, deverá condenar Paulo a reembolsar as despesas suportadas por Maria, bem como a pagar honorários em favor do advogado dela."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2024 • TEC 3228697","source":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3228697","year":2024,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2340289","sourceQuestionId":"2340289","t":"cpc-m11","moduleId":"cpc-m11","q":"Em ação movida por Pedro contra José, este arguiu, em preliminar de contestação, sua ilegitimidade passiva, indicando Patrícia como sujeito passivo da relação jurídica discutida no processo. Nesse caso, de acordo com o Código de Processo Civil, o juiz deverá","o":["facultar a Pedro a alteração da petição inicial para substituição do réu, sendo que, realizada a substituição, Pedro reembolsará as despesas de José, mas ficará isento do pagamento de honorários ao procurador deste.","facultar a Pedro a alteração da petição inicial para substituição do réu, sendo que, realizada a substituição, Pedro reembolsará as despesas de José e pagará honorários ao procurador deste.","extinguir o processo sem resolução do mérito, caso conclua pela ilegitimidade de José, sendo-lhe vedado facultar a Pedro a emenda da petição inicial para substituição do réu depois de apresentada a contestação.","extinguir o processo com resolução do mérito, caso conclua pela ilegitimidade de José, sendo-lhe vedado facultar a Pedro a emenda da petição inicial para substituição do réu depois de apresentada a contestação.","determinar a substituição de José por Patrícia, independentemente de pedido ou mesmo da concordância de Pedro, caso conclua que ela é, de fato, sujeito passivo da relação jurídica discutida no processo."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT18/TRT 18/Judiciária/\"Sem Especialidade\"/2023 • TEC 2340289","source":"FCC - AJ TRT18/TRT 18/Judiciária/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2340289","year":2023,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2160146","sourceQuestionId":"2160146","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, a incompetência relativa deve ser alegada","o":["a qualquer tempo e grau de jurisdição, por simples petição.","por meio de exceção de incompetência, que será distribuída no prazo da contestação.","na contestação, que poderá ser protocolada no foro do domicílio do réu, ainda que a ação haja sido proposta em local diverso.","na contestação, que deverá ser protocolada necessariamente no local da propositura da ação, a fim de possibilitar a realização de audiência de conciliação.","por meio de exceção de incompetência, a qualquer tempo e grau de jurisdição."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT22/TRT 22/Área Judiciária/\"Sem Especialidade\"/2022 • TEC 2160146","source":"FCC - AJ TRT22/TRT 22/Área Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2160146","year":2022,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2271826","sourceQuestionId":"2271826","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, é lícito ao réu deduzir novas alegações depois da contestação","o":["somente quando relativas a direito ou a fato superveniente.","relativas a fato superveniente, mas não a direito superveniente, ressalvado, quanto a este, o ajuizamento de ação incidental, a ser distribuída por prevenção.","quando competir ao juiz conhecer delas de ofício.","sempre que ao autor tiver sido concedida a réplica.","sempre que a demanda versar sobre direitos indisponíveis, independentemente das questões de fato ou de direito a que se refiram."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT17/TRT 17/Judiciária/\"Sem Especialidade\"/2022 • TEC 2271826","source":"FCC - AJ TRT17/TRT 17/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2271826","year":2022,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2454175","sourceQuestionId":"2454175","t":"cpc-m11","moduleId":"cpc-m11","q":"Danilo foi citado em ação petitória, em que se discute a propriedade do imóvel no qual ele reside. Ao procurar a Defensoria Pública, este afirmou que gostaria de alegar a usucapião do bem, já que mora no local com posse mansa e pacífica há mais de 15 anos. Conforme entendimento dominante dos Tribunais Superiores sobre o assunto, a usucapião","o":["poderá ser arguida como defesa na própria contestação.","deverá ser pleiteada em reconvenção, porquanto não se admite sua arguição em sede de defesa.","não poderá ser alegada nessa demanda, pois há vedação legal no sentido de impedir a discussão sobre posse e propriedade no mesmo processo.","deverá ser requerida em demanda autônoma somente após o trânsito em julgado da ação petitória.","poderá ser arguida em ação rescisória incidental, desde que a modalidade de usucapião pleiteada seja a ordinária."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2022 • TEC 2454175","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2022","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2454175","year":2022,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-840070","sourceQuestionId":"840070","t":"cpc-m11","moduleId":"cpc-m11","q":"Humberto comparece à unidade da Defensoria Pública da cidade onde reside, no interior do Estado, informando que recebeu citação de uma demanda em que se discutem direitos reais sobre bens móveis, proposta na capital do mesmo Estado, sendo intimado no mesmo ato do prazo para a apresentação de resposta. Humberto discorda do pedido do autor e deseja apresentar defesa. Diante desta situação, o Defensor lotado no interior do Estado deverá","o":["elaborar a peça defensiva de contestação, com a alegação de incompetência do juízo em preliminar de contestação, hipótese em que poderá protocolar a contestação no foro de domicílio do réu.","orientar Humberto para que compareça ao atendimento da Defensoria Pública na Capital, onde deverão ser tomadas as medidas em sua defesa, inclusive a elaboração de contestação.","elaborar a peça defensiva de contestação, protocolando-a necessariamente no foro da Capital, onde está sendo processada a ação, em razão da existência de norma de competência absoluta quanto ao foro da situação do bem.","elaborar a peça defensiva de contestação, que poderá ser protocolada no foro de domicílio do réu, ainda que não apresente preliminar de incompetência do juízo.","elaborar a peça defensiva de contestação, que somente poderá ser protocolada no foro de domicílio do réu se a carta precatória ainda não tiver sido devolvida ao juízo deprecante."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP SP/DPE SP/2019 • TEC 840070","source":"FCC - DP SP/DPE SP/2019","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/840070","year":2019,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1014417","sourceQuestionId":"1014417","t":"cpc-m11","moduleId":"cpc-m11","q":"Renata ajuizou ação de indenização por danos materiais contra Almeida, atribuindo-lhe a culpa por acidente de trânsito que resultou na danificação do seu automóvel. Em sua contestação, Almeida alegou não ser parte legítima, nem responsável pelo dano, por não ser proprietário nem condutor do veículo que colidiu com o automóvel de Renata. Nesse caso, o juiz deverá","o":["julgar de plano a lide, extinguindo o processo sem resolução do mérito, se a contestação vier instruída de prova bastante da alegação de Almeida; além disso, condenará Renata a reembolsar as despesas e a pagar honorários ao procurador de Almeida.","julgar de plano a lide, extinguindo o processo sem resolução do mérito, se a contestação vier instruída de prova bastante da alegação de Almeida; entretanto, não condenará Renata a reembolsar as despesas ou a pagar honorários ao procurador de Almeida, salvo comprovada má-fé.","julgar de plano a lide, extinguindo o processo com resolução do mérito, se a contestação vier instruída de prova bastante da alegação de Almeida; além disso, condenará Renata a reembolsar as despesas e a pagar honorários ao procurador de Almeida.","facultar a Renata, em quinze dias, a alteração da petição inicial para substituição do réu; realizada a substituição, caberá a Renata reembolsar as despesas e pagar honorários ao procurador de Almeida.","facultar a Renata, em quinze dias, a alteração da petição inicial para substituição do réu; mesmo se realizada a substituição, não caberá a Renata reembolsar as despesas ou pagar os honorários ao procurador de Almeida, salvo comprovada má-fé."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - CL (CM Fortal)/CM Fortaleza/Advogado/2019 • TEC 1014417","source":"FCC - CL (CM Fortal)/CM Fortaleza/Advogado/2019","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1014417","year":2019,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592913","sourceQuestionId":"592913","t":"cpc-m11","moduleId":"cpc-m11","q":"Em contestação, incumbe ao réu,","o":["alegar litispendência, que se configura quando se repete ação que já foi definitivamente julgada.","alegar, antes de discutir o mérito, incompetência absoluta e relativa, esta última por meio de exceção, por petição em apartado.","indicar o sujeito passivo da relação jurídica discutida sempre que tiver conhecimento, quando alegar sua ilegitimidade, sob pena de arcar com as despesas processuais e de indenizar o autor pelos prejuízos decorrentes da falta de indicação.","levantar a existência de convenção de arbitragem, que também pode ser conhecida de ofício pelo juiz.","alegar toda a matéria de defesa, só se permitindo deduzir novas alegações quando competir ao juiz conhecer delas de ofício."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2018 • TEC 592913","source":"FCC - Proc (PGE TO)/PGE TO/2018","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592913","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-653920","sourceQuestionId":"653920","t":"cpc-m11","moduleId":"cpc-m11","q":"Mateus ajuizou ação de indenização por danos morais e materiais contra Moisés, manifestando expressamente, na própria inicial, o desinteresse na composição consensual. Ao receber a peça inicial, que preenche todos os requisitos legais, o Magistrado designa audiência de conciliação e determina a citação do réu com pelo menos 20 dias da data agendada para o ato processual. Após ser citado e intimado para comparecer à audiência conciliatória designada, Moisés protocola, por meio do seu advogado, petição manifestando expressamente desinteresse na composição amigável. Nesse caso, o réu Moisés poderá oferecer contestação no prazo de 15 dias, cujo termo inicial será a data","o":["da intimação do réu da decisão do Magistrado que deferiu o pedido de cancelamento da audiência.","da juntada do novo mandado de citação, necessário para a lide em questão diante do cancelamento da audiência conciliatória.","da audiência conciliatória designada, de caráter obrigatório, que não será cancelada mesmo com os pedidos veiculados pelas partes.","do protocolo da sua petição postulando o cancelamento da audiência conciliatória.","da nova citação do réu, após o deferimento do pedido de cancelamento da audiência."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2018 • TEC 653920","source":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2018","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/653920","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-653921","sourceQuestionId":"653921","t":"cpc-m11","moduleId":"cpc-m11","q":"Manoela ajuizou ação de cobrança contra Suzana, objetivando o recebimento da quantia de R$ 18.000,00 decorrente de um serviço de assessoria prestado durante o ano de 2017. Recebida a inicial e determinada a citação da ré, a contestação é apresentada no prazo legal, com arguição preliminar de ilegitimidade de parte passiva e impugnação integral ao pleito inicial no mérito. Neste caso, nos termos estabelecidos pelo Código de Processo Civil,","o":["o juiz facultará ao autor, em 15 dias, a alteração da petição inicial para substituição do réu e, realizada a substituição, o autor reembolsará as despesas e pagará os honorários ao procurador do réu excluído, que serão fixados, em regra, entre três e cinco por cento do valor da causa.","não é admitida a substituição do réu após a consumação da citação, cabendo ao juiz extinguir o processo sem resolver o mérito no caso de acolhimento da preliminar arguida.","o juiz facultará ao autor, em 15 dias, a alteração da petição inicial para substituição do réu e, realizada a substituição, o autor não reembolsará as despesas processuais e também não pagará honorários ao procurador do réu excluído.","o juiz facultará ao autor, em 5 dias, a alteração da petição inicial para substituição do réu e, realizada a substituição, o autor reembolsará as despesas e pagará os honorários ao procurador do réu excluído, que serão fixados, em regra, entre três e cinco por cento do valor da causa.","o juiz facultará ao autor, em 5 dias, a alteração da petição inicial para substituição do réu e, realizada a substituição, o autor não reembolsará as despesas e também não pagará os honorários ao procurador do réu excluído."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2018 • TEC 653921","source":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2018","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/653921","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-677641","sourceQuestionId":"677641","t":"cpc-m11","moduleId":"cpc-m11","q":"Considere os enunciados seguintes, concernentes à contestação: I. Em obediência ao princípio da eventualidade, incumbe ao réu alegar, na contestação, toda a matéria de defesa, expondo as razões de fato e de direito com que impugna o pedido do autor e especificando as provas que pretende produzir. II. Alegando o réu, na contestação, ser parte ilegítima ou não ser o responsável pelo prejuízo invocado, o juiz facultará ao autor, em quinze dias, a alteração da petição inicial para substituição do réu. III. Quando alegar sua ilegitimidade, incumbe ao réu indicar o sujeito passivo da relação jurídica discutida sempre que tiver conhecimento, sob pena de arcar com as despesas processuais e de indenizar o autor pelos prejuízos decorrentes da falta de indicação. IV. Incumbe ao réu manifestar-se precisamente sobre as alegações de fato e de direito constantes da petição inicial, em obediência ao ônus da impugnação especificada dos fatos, que só admite exceções à contestação oferecida pelo defensor público ou pelo curador especial. V. Depois da contestação, só é lícito ao réu deduzir novas alegações quando relativas a direito ou a fatos supervenientes. Está correto o que se afirma APENAS em","o":["I, III, IV e V.","II, IV e V.","I, II e III.","III, IV e V.","I, II, IV e V."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE AP)/PGE AP/2018 • TEC 677641","source":"FCC - Proc (PGE AP)/PGE AP/2018","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/677641","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-985008","sourceQuestionId":"985008","t":"cpc-m11","moduleId":"cpc-m11","q":"Na hipótese de ser concedida gratuidade da justiça quando do recebimento da petição inicial, o réu poderá impugnar esta decisão","o":["em preliminar de contestação, sem a instauração de incidente apartado.","por agravo de instrumento, sob pena de preclusão.","mediante petição própria que instaura incidente apartado de impugnação à concessão da gratuidade da justiça.","por simples petição, no prazo de quinze dias a partir da data da citação, sob pena de preclusão.","por simples petição e a qualquer tempo do processo, uma vez que o deferimento da gratuidade não gera preclusão."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP SC/DPE SC/2017 • TEC 985008","source":"FCC - DP SC/DPE SC/2017","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/985008","year":2017,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-396150","sourceQuestionId":"396150","t":"cpc-m11","moduleId":"cpc-m11","q":"Sobre as respostas do réu, é correto afirmar:","o":["Para o réu propor reconvenção é necessário que apresente contestação.","Se o réu, na contestação, deixar de alegar incompetência absoluta ou relativa, o juiz conhecerá de tais matérias de ofício.","Havendo alegação de incompetência relativa ou absoluta, a contestação poderá ser protocolada no foro de domicílio do réu.","A desistência da ação ou a ocorrência de causa extintiva que impeça o exame de seu mérito obsta o prosseguimento do processo quanto à reconvenção.","Na contestação, é lícito ao réu propor reconvenção para manifestar pretensão própria, ainda que não conexa com a ação principal nem com o fundamento da defesa."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2016 • TEC 396150","source":"FCC - DP BA/DPE BA/2016","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/396150","year":2016,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-292799","sourceQuestionId":"292799","t":"cpc-m11","moduleId":"cpc-m11","q":"Fernando ajuizou ação contra Priscila sustentando que esta, por culpa, abalroou seu veículo, causando-lhe danos exclusivamente materiais, os quais estariam comprovados por recibos de pagamento que anexou à petição inicial. De acordo com Fernando, o valor dos danos, já atualizado monetariamente e acrescido de juros legais, seria de R$ 8.000,00. Com base, exclusivamente, na prova documental, requereu a condenação de Priscila ao pagamento de R$ 15.000,00 a título de indenização por danos materiais. Em contestação, Priscila negou ter agido com culpa. No entanto, não impugnou o valor do pedido de indenização. Se o Juiz se convencer de que Priscila tem responsabilidade pelo acidente, deverá","o":["julgar totalmente procedente o pedido, condenando-a ao pagamento de R$ 15.000,00, tendo em vista caber ao Réu, na contestação, alegar toda a matéria de defesa, presumindo-se verdadeiros, de maneira absoluta, os fatos não impugnados.","julgar parcialmente procedente o pedido, condenando- a ao pagamento de R$ 8.000,00, tendo em vista ser relativa a presunção de veracidade decorrente da ausência de impugnação específica.","indeferir a petição inicial e extinguir o processo sem resolução de mérito, pois da narrativa não decorre logicamente o pedido.","julgar improcedente o pedido, pois Fernando utilizou o processo para obter objetivo ilegal, o que deve ser coibido pelo Poder Judiciário.","julgar parcialmente procedente o pedido, condenando- a ao pagamento de R$ 8.000,00, tendo em vista que, apesar de absoluta a presunção de veracidade decorrente da ausência de impugnação específica, Fernando utilizou o processo para obter objetivo ilegal, o que deve ser coibido pelo Poder Judiciário."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT3/TRT 3/Judiciária/\"Sem Especialidade\"/2015 • TEC 292799","source":"FCC - AJ TRT3/TRT 3/Judiciária/\"Sem Especialidade\"/2015","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/292799","year":2015,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-322369","sourceQuestionId":"322369","t":"cpc-m11","moduleId":"cpc-m11","q":"Verificando que o réu estava preso, cumprindo pena de reclusão em regime fechado por crime de homicídio, o juiz nomeou um advogado que se achava então na sala de audiências, aguardando a chamada de outro processo, para representar aquele réu como curador. Aberta a audiência e recusada a conciliação, o advogado nomeado declarou que negava todos os fatos articulados na petição inicial e protestava por todas as provas em direito admitidas. Seria legalmente respaldado o entendimento no sentido de que","o":["todos os ônus da prova cabem ao autor.","o réu deveria ser considerado confesso, por falta de contestação específica.","os ônus da prova deveriam ser distribuídos em carga dinâmica.","todos os ônus da prova ficariam com o réu.","a distribuição dos ônus da prova dependerá do que disserem as partes em depoimento."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT1/TRT 1/2015 • TEC 322369","source":"FCC - JT TRT1/TRT 1/2015","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/322369","year":2015,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-216896","sourceQuestionId":"216896","t":"cpc-m11","moduleId":"cpc-m11","q":"Em relação à ação, é correto afirmar:","o":["Os elementos da ação são as partes, o pedido e a causa de pedir, servindo para identificá-la e não se confundindo com suas condições.","Se os elementos da ação forem idênticos, ter-se-á a configuração de continência ou conexão, conforme a natureza da demanda.","Se os elementos da ação forem semelhantes, ter-se-á a caracterização de litispendência ou coisa julgada.","O direito de ação em sentido estrito é incondicionado, por decorrer do direito de acesso à justiça.","As condições da ação constituem matéria de ordem pública e, assim, devem ser arguidas pela parte, não podendo ser reconhecidas de ofício pelo juiz."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PB/DPE PB/2014 • TEC 216896","source":"FCC - DP PB/DPE PB/2014","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/216896","year":2014,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-216914","sourceQuestionId":"216914","t":"cpc-m11","moduleId":"cpc-m11","q":"A resposta do réu","o":["dada na contestação, implica a apresentação de todas as razões que possam levar ao desacolhimento do pedido inicial, em obediência ao princípio da eventualidade, além de especificar as provas que pretende produzir.","é oferecida sempre em peça única, que engloba a contestação, a reconvenção e as exceções legal mente previstas.","dada em exceção de incompetência relativa, implica a prolação de sentença, da qual caberá apelação.","é sempre meritória, ainda que diga respeito a matérias de ordem pública, saIvo se arguidos pressupostos de inadmissibilidade da demanda.","deve conter na contestação todas as alegações fáticas e de direito possíveis, em nenhuma hipótese admitindo-se a dedução de novas alegações."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PB/DPE PB/2014 • TEC 216914","source":"FCC - DP PB/DPE PB/2014","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/216914","year":2014,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3375455","sourceQuestionId":"3375455","t":"cpc-m11","moduleId":"cpc-m11","q":"Sobre a contestação e a reconvenção no Código de Processo Civil:","o":["Para que o réu possa propor reconvenção, é obrigatório que ele tenha também apresentado contestação veiculando defesa em relação à ação principal.","Nos casos em que a ação principal houver sido proposta por substituto processual, a reconvenção deverá ser proposta contra o substituído.","O ônus da impugnação especificada dos fatos aplica-se ao defensor público apenas nos casos em que ele atuar como curador especial.","A extinção do processo sem resolução do mérito em relação à ação principal por força do não atendimento a um pressuposto processual impõe a extinção do processo em relação à reconvenção por perda de interesse de agir.","É lícito ao réu, mesmo depois de transcorrido o prazo legal para a apresentação de contestação, apresentar petição alegando prescricao do direito do autor."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2025 • TEC 3375455","source":"FCC - DP RS/DPE RS/2025","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3375455","year":2025,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3554464","sourceQuestionId":"3554464","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, na contestação","o":["o réu deve, antes do mérito, alegar a ocorrência de prescrição, cujo reconhecimento acarreta a extinção do processo sem resolução de mérito.","é defeso ao réu alegar a incompetência absoluta ou relativa.","incumbe ao réu manifestar-se sobre as alegações de fato constantes da petição inicial, presumindo-se verdadeiras as não impugnadas, inclusive se a seu respeito não for admissível a confissão.","é lícito ao réu propor reconvenção para manifestar pretensão própria, conexa com a ação principal ou com o fundamento da defesa.","o réu deve, antes do mérito, alegar a ocorrência de coisa Julgada, cujo reconhecimento acarreta a extinção do processo com resolução de mérito."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Min (MPE PI)/MPE PI/Processual/2025 • TEC 3554464","source":"FCC - Ana Min (MPE PI)/MPE PI/Processual/2025","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3554464","year":2025,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126491","sourceQuestionId":"3126491","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, a desistência da ação","o":["independe, em qualquer caso, do consentimento do réu.","implica, quando homologada, extinção do processo com resolução de mérito.","produz efeitos independentemente de homologação judicial.","pode ser apresentada apenas até a contestação.","não obsta o prosseguimento do processo em relação à reconvenção."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126491","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126491","year":2024,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2850454","sourceQuestionId":"2850454","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, a reconvenção","o":["pode ser proposta independentemente do oferecimento de contestação.","deve ser apresentada por petição autônoma, no prazo da contestação.","segue a mesma sorte da ação principal, cuja extinção ou desistência obsta o seu prosseguimento.","é cabível, independentemente de qualquer requisito, no âmbito dos Juizados Especiais Cíveis.","é cabível no âmbito dos Juizados Especiais Cíveis apenas se a pretensão reconvencional for conexa com a ação principal ou com fundamento da defesa."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT21/TRT 21/Administrativa/\"Sem Especialidade\"/2023 • TEC 2850454","source":"FCC - TJ TRT21/TRT 21/Administrativa/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2850454","year":2023,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021920","sourceQuestionId":"2021920","t":"cpc-m11","moduleId":"cpc-m11","q":"A reconvenção","o":["só pode ser proposta contra o autor.","não necessita conter valor à causa.","pode ser proposta independentemente da contestação.","segue a sorte da ação, não podendo ser analisada se houver desistência, pelo autor.","deve ser respondida pela parte contrária no prazo de 5 dias, contado da juntada da reconvenção aos autos digitais."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ass Proc (PGE AM)/PGE AM/2022 • TEC 2021920","source":"FCC - Ass Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021920","year":2022,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2230501","sourceQuestionId":"2230501","t":"cpc-m11","moduleId":"cpc-m11","q":"Analise as asserções abaixo. I. A desistência da ação pelo autor não obsta o prosseguimento do processo quanto à reconvenção. PORQUE II. O réu pode propor reconvenção independentemente de oferecer contestação. É correto afirmar que","o":["as asserções I e II são proposições verdadeiras e a II é uma justificativa da I.","as asserções I e II são proposições verdadeiras, mas a II não é uma justificativa da I.","as asserções I e II são proposições falsas.","a asserção I é uma proposição verdadeira e a II é uma proposição falsa.","a asserção I é uma proposição falsa e a II é uma proposição verdadeira."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2022 • TEC 2230501","source":"FCC - DP MT/DPE MT/2022","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2230501","year":2022,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1736857","sourceQuestionId":"1736857","t":"cpc-m11","moduleId":"cpc-m11","q":"A reconvenção","o":["pode ser proposta apenas pelo réu contra o próprio autor.","não leva, se improcedente, à condenação em honorários advocatícios, os quais são devidos apenas pela procedência do pedido principal.","só pode ser proposta se oferecida contestação.","prossegue mesmo que ocorra causa extintiva que impeça o exame de mérito da ação principal.","dispensa a atribuição de valor à causa."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJGO/TJ GO/2021 • TEC 1736857","source":"FCC - JE TJGO/TJ GO/2021","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1736857","year":2021,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1009179","sourceQuestionId":"1009179","t":"cpc-m11","moduleId":"cpc-m11","q":"Quanto às providências preliminares e ao saneamento do processo, é correto afirmar:","o":["Se o réu não contestar a ação, o juiz deverá, em qualquer hipótese, aplicar o efeito da revelia e julgar de imediato a lide.","Na contestação, é lícito ao réu propor reconvenção para manifestar pretensão própria, conexa com a ação principal ou com o fundamento da defesa.","Ao réu revel será possível ingressar no processo em qualquer tempo, desde que não proferida sentença, hipótese na qual terá precluído essa possibilidade.","Verificando a existência de irregularidades ou vícios sanáveis, o juiz determinará sua correção em prazo nunca superior a quinze dias.","Cumpridas as providências preliminares ou não havendo necessidade delas, o juiz obrigatoriamente saneará o processo, delimitando os fatos sobre os quais recairá a produção de prova."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ (TJ MA)/TJ MA/Direito/2019 • TEC 1009179","source":"FCC - AJ (TJ MA)/TJ MA/Direito/2019","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1009179","year":2019,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592254","sourceQuestionId":"592254","t":"cpc-m11","moduleId":"cpc-m11","q":"Pedro ajuizou ação de cobrança em face de João. No prazo para resposta, João comparece à Defensoria Pública, onde apresenta alguns documentos que demonstram ser ele credor de dívida já vencida em valor superior àquela que lhe está sendo cobrada. O defensor responsável pela defesa dos interesses de João deverá explicar que, para cobrar a dívida de Pedro,","o":["não é necessário ajuizar ação autônoma ou reconvir, bastando que em sua contestação pleiteie a compensação e a condenação do autor, sem a necessidade de qualquer outro requisito.","será necessário ajuizar uma ação autônoma de cobrança, sem prejuízo da defesa de João na demanda que aquele move contra este.","é possível propor reconvenção, desde que haja compatibilidade entre os ritos, competência para conhecer da demanda reconvencional, devendo ser a reconvenção apresentada no bojo da própria contestação.","deve apresentar pedido contraposto, diante da natureza dúplice da obrigação descrita no problema, sendo inútil e desnecessária a reconvenção neste caso.","é possível propor reconvenção, independentemente da existência de compatibilidade entre os ritos ou da competência para conhecer da demanda reconvencional, devendo ser a reconvenção apresentada em peça separada da contestação."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2018 • TEC 592254","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592254","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592919","sourceQuestionId":"592919","t":"cpc-m11","moduleId":"cpc-m11","q":"Em relação à reconvenção, está correto afirmar:","o":["O réu só pode propor reconvenção de forma condicionada ao oferecimento de contestação ao pedido inicial.","Se o autor for substituto processual, o reconvinte deverá afirmar ser titular de direito em face do substituído, e a reconvenção deverá ser proposta em face do autor, também na qualidade de substituto processual.","A desistência da ação ou a ocorrência de causa extintiva que impeça o exame de seu mérito obsta ao prosseguimento do processo quanto à reconvenção, haja vista seu caráter de subordinação ao pedido principal.","A reconvenção pode ser proposta pelo réu, defeso porém o litisconsórcio com terceiro.","É lícito ao réu propor reconvenção na contestação ou por petição autônoma, para manifestar pretensão própria, conexa ou não com a ação principal ou com o fundamento da causa."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2018 • TEC 592919","source":"FCC - Proc (PGE TO)/PGE TO/2018","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592919","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-682590","sourceQuestionId":"682590","t":"cpc-m11","moduleId":"cpc-m11","q":"Em relação à reconvenção,","o":["a desistência da ação ou a ocorrência de causa extintiva que impeça o exame de seu mérito obsta o prosseguimento do processo quanto à reconvenção, por seu caráter acessório.","proposta a reconvenção, o autor será citado, pessoalmente, por via postal, para apresentar resposta no prazo de quinze dias.","se o autor for substituto processual, o reconvinte deverá afirmar ser titular de direito em face do substituído, e a recon venção deverá ser proposta em face do autor, também na qualidade de substituto processual.","a reconvenção pode ser proposta somente contra o autor, sendo também possível seu ajuizamento pelo réu em litis consórcio com terceiro.","a reconvenção só pode ser proposta pelo réu se oferecida por ele contestação simultaneamente, na mesma peça de defesa."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc Leg (CL DF)/CL DF/2018 • TEC 682590","source":"FCC - Proc Leg (CL DF)/CL DF/2018","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/682590","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-394334","sourceQuestionId":"394334","t":"cpc-m11","moduleId":"cpc-m11","q":"Considere as assertivas a seguir sobre a reconvenção. I. Na contestação, é lícito ao réu propor reconvenção para manifestar pretensão própria, conexa com a ação principal ou com o fundamento da defesa. II. O réu não pode propor reconvenção se não oferecer contestação. III. A desistência da ação ou a ocorrência de causa extintiva que impeça o exame de seu mérito obsta o prosseguimento da reconvenção. IV. A reconvenção pode ser proposta contra o autor e terceiro ou pelo réu em litisconsórcio com terceiro. V. Se o autor for substituto processual, o reconvinte deverá afirmar ser titular de direito em face do substituído, e a reconvenção deverá ser proposta em face do autor, também na qualidade de substituto processual. É correto o que se afirma APENAS em","o":["II, IV e V.","I, II e III.","I, IV e V.","II, III e IV.","III, IV e V."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MA)/PGE MA/2016 • TEC 394334","source":"FCC - Proc (PGE MA)/PGE MA/2016","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/394334","year":2016,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-410680","sourceQuestionId":"410680","t":"cpc-m11","moduleId":"cpc-m11","q":"Carlito ajuizou ação de indenização contra João Paulo no âmbito da qual sustenta que o réu lhe causou lesões corporais das quais resultaram danos morais, que deseja ver compensados. Por outro lado, João Paulo julga que Carlito também lhe causou lesões corporais e também deseja ser compensado por danos morais. Pretendendo reconvir, João Paulo deverá, de acordo com o Código de Processo Civil em vigor, propor reconvenção na contestação,","o":["ou apenas reconvir, sem apresentar contestação. Se Carlito desistir da ação, a desistência não obstará o prosseguimento do processo quanto à reconvenção.","não podendo apenas reconvir, sob pena de, em não apresentando contestação, não ser conhecida a reconvenção. Se Carlito desistir da ação, a desistência não obstará o prosseguimento do processo quanto à reconvenção.","ou apenas reconvir, sem apresentar contestação. Se Carlito desistir da ação, a desistência prejudicará a reconvenção, obstando o prosseguimento do processo.","não podendo apenas reconvir, sob pena de, em não apresentando contestação, não ser conhecida a reconvenção. Se Carlito desistir da ação, a desistência prejudicará a reconvenção, obstando o prosseguimento do processo.","ou em peça apartada, não podendo apenas reconvir, sob pena de, em não apresentando contestação, não ser conhecida a reconvenção. Se Carlito desistir da ação, a desistência prejudicará a reconvenção, obstando o prosseguimento do processo."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - ALegis (ALMS)/ALMS/Jurídico/2016 • TEC 410680","source":"FCC - ALegis (ALMS)/ALMS/Jurídico/2016","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/410680","year":2016,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-177953","sourceQuestionId":"177953","t":"cpc-m11","moduleId":"cpc-m11","q":"Eduardo ajuíza ação de indenização contra Pedro, que apresenta contestação e reconvenção. Depois da resposta, porém, Eduardo formula pedido de desistência, sem contestar a reconvenção. Pedro aceita o pedido de desistência, mas requer o prosseguimento da reconvenção. O juiz deverá","o":["homologar a desistência e dar prosseguimento à reconvenção, mas sem declarar a revelia de Eduardo.","homologar a desistência e julgar o processo extinto sem julgamento de mérito, deixando de apreciar o pedido reconvencional.","indeferir o pedido de desistência e dar prosseguimento à reconvenção, declarando a revelia de Eduardo.","homologar a desistência, dar prosseguimento à reconvenção e declarar a revelia de Eduardo.","indeferir o pedido de desistência e dar prosseguimento à reconvenção, mas sem declarar a revelia de Eduardo."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc Jud (Pref Recife)/Pref Recife/2014 • TEC 177953","source":"FCC - Proc Jud (Pref Recife)/Pref Recife/2014","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/177953","year":2014,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-251379","sourceQuestionId":"251379","t":"cpc-m11","moduleId":"cpc-m11","q":"Em relação à contestação e à reconvenção,","o":["pode o réu, em seu próprio nome, reconvir ao autor, quando este demandar em nome de outrem.","depois da contestação, só é lícito deduzir novas alegações quando competir ao juiz conhecer delas de ofício.","entre outras razões, compete ao réu alegar em contestação, antes de discutir o mérito, a incompetência absoluta, a perempção, a litispendência, a coisa julgada e a conexão.","a desistência da ação, ou a existência de qualquer causa que a extinga, obsta ao prosseguimento da reconvenção, por ser ela subordinada à ação da qual proveio.","julgar-se-ão por sentenças autônomas a ação e a reconvenção."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP CE/DPE CE/2014 • TEC 251379","source":"FCC - DP CE/DPE CE/2014","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/251379","year":2014,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3228695","sourceQuestionId":"3228695","t":"cpc-m11","moduleId":"cpc-m11","q":"O artigo 344 do Código de Processo Civil dispõe que, se o réu não contestar a ação, será considerado revel e presumir-se-ão verdadeiras as alegações de fato formuladas pelo autor. A revelia produzirão esse efeito mesmo se","o":["as alegações de fato formuladas pelo autor forem inverossímeis.","houver litisconsórcio passivo e algum dos réus contestar a ação.","o réu apresentar contestação intempestiva, mas antes do julgamento da ação.","o litígio versar sobre direitos indisponíveis.","as alegações de fato formuladas pelo autor estiverem em contradição com a prova constante dos autos."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2024 • TEC 3228695","source":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3228695","year":2024,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2850453","sourceQuestionId":"2850453","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, a revelia","o":["impede que o juiz determine a produção de provas.","não impede que o revel intervenha no processo.","induz presunção absoluta de veracidade das alegações de fato formuladas pelo autor, ainda que o litígio verse sobre direitos indisponíveis.","induz presunção relativa de veracidade das alegações de fato formuladas pelo autor, ainda que o litígio verse sobre direitos indisponíveis.","impõe o julgamento antecipado do mérito."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT21/TRT 21/Administrativa/\"Sem Especialidade\"/2023 • TEC 2850453","source":"FCC - TJ TRT21/TRT 21/Administrativa/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2850453","year":2023,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2038258","sourceQuestionId":"2038258","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o art. 344, do Código de Processo Civil, se o réu não contestar a ação, será considerado revel e, por consequência, serão presumidas verdadeiras as alegações de fato formuladas pelo autor. Tal efeito incidirá","o":["somente se houver verossimilhança nas alegações autorais e não estiver em contradição com nenhuma prova produzida nos autos.","em uma ação com pedido de declaração da paternidade em que o réu deixou de contestar.","ainda que algum corréu tenha contestado o pedido do autor, diante do princípio da autonomia dos litisconsortes.","mesmo se o réu for citado por edital e houver apresentação de contestação por negativa geral pelo defensor público, por ausência de impugnação específica dos fatos.","salvo exceções legais, inviabilizando a atividade probatória do réu revel."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP CE/DPE CE/2022 • TEC 2038258","source":"FCC - DP CE/DPE CE/2022","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2038258","year":2022,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2239321","sourceQuestionId":"2239321","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, se o réu não contestar a ação, será considerado revel e presumir-se-ão verdadeiras as alegações de fato formuladas pelo autor. Ainda segundo o mesmo diploma, essa presunção","o":["aplica-se apenas em relação ao réu que tiver deixado de contestar a ação, se esta tiver sido proposta contra mais de uma pessoa, ainda que outro réu tenha tempestivamente apresentado contestação.","não se aplica se as alegações de fato formuladas pelo autor forem inverossímeis.","não se aplica se o réu for pessoa menor de 18 (dezoito) anos ou maior de 60 (sessenta) anos de idade.","aplica-se mesmo quando o litígio versar sobre direitos indisponíveis, salvo apenas se o réu for pessoa incapaz.","aplica-se mesmo quando as alegações de fato formuladas pelo autor estiverem em contradição com as provas constantes dos autos, já que, com a revelia, o juiz deverá se abster de analisá-las."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT14/TRT 14/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2239321","source":"FCC - AJ TRT14/TRT 14/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2239321","year":2022,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1984108","sourceQuestionId":"1984108","t":"cpc-m11","moduleId":"cpc-m11","q":"A revelia","o":["pode ocasionar o julgamento antecipado do pedido, caso a parte autora não faça requerimento de produção de provas.","induz presunção absoluta de veracidade dos fatos alegados pela parte autora na petição inicial.","somente não gera a presunção de veracidade se as alegações de fato formuladas pela parte autora forem inverossímeis ou estiverem em contradição com prova constante dos autos.","não impede que o revel intervenha no processo no estado em que se encontre, desde que o faça antes da prolação de sentença.","contempla apenas a situação do réu que, citado pessoalmente, deixar de constituir advogado e apresentar defesa no prazo; aquele que constitui advogado no prazo, embora não apresente defesa, não pode ser considerado revel."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2021 • TEC 1984108","source":"FCC - DP AM/DPE AM/2021","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1984108","year":2021,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-943729","sourceQuestionId":"943729","t":"cpc-m11","moduleId":"cpc-m11","q":"Rodolfo ajuizou ação contra Felipe, versando o litígio sobre direito indisponível. Devidamente citado, o réu não ofereceu contestação no prazo legal, tornando-se revel. Nesse caso, a revelia","o":["impõe que o pedido seja julgado procedente.","torna precluso o direito de produzir provas.","veda a interposição de recurso contra a sentença.","impede o réu de intervir no processo, salvo na fase de cumprimento de sentença.","não enseja a presunção da veracidade das alegações de fato formuladas pelo autor."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF4/TRF 4/Administrativa/\"Sem Especialidade\"/2019 • TEC 943729","source":"FCC - TJ TRF4/TRF 4/Administrativa/\"Sem Especialidade\"/2019","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/943729","year":2019,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-714234","sourceQuestionId":"714234","t":"cpc-m11","moduleId":"cpc-m11","q":"A presunção de veracidade decorrente da revelia processual é","o":["absoluta em matéria patrimonial e relativa quando se referir a direitos indisponíveis.","absoluta e diz respeito à matéria de fato e de direito.","relativa e diz respeito somente à matéria de direito.","absoluta, mas diz respeito apenas à matéria de direito.","relativa e diz respeito somente à matéria fática."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Prom Jus (MPE PB)/MPE PB/2018 • TEC 714234","source":"FCC - Prom Jus (MPE PB)/MPE PB/2018","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/714234","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-455579","sourceQuestionId":"455579","t":"cpc-m11","moduleId":"cpc-m11","q":"A respeito do procedimento comum, considere: I. Incumbe ao réu, na contestação, antes de discutir o mérito, alegar a incompetência absoluta ou relativa. II. Proposta a reconvenção, o autor será citado pessoalmente para apresentar contestação no prazo de 10 dias. III. Ao réu revel será lícita a produção de provas, contrapostas às alegações do autor, desde que se faça representar nos autos em tempo de praticar os atos processuais indispensáveis à sua produção. Está correto o que se afirma APENAS em","o":["II.","I e II.","II e III.","I.","I e III."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT11/TRT 11/Judiciária/Oficial de Justiça Avaliador Federal/2017 • TEC 455579","source":"FCC - AJ TRT11/TRT 11/Judiciária/Oficial de Justiça Avaliador Federal/2017","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/455579","year":2017,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-337638","sourceQuestionId":"337638","t":"cpc-m11","moduleId":"cpc-m11","q":"Se o Réu for revel,","o":["os prazos correrão independentemente de intimação, não podendo o revel intervir no processo.","serão aplicados os efeitos da revelia inclusive a presunção de veracidade dos fatos alegados pelo autor, ainda que o litígio verse sobre direitos indisponíveis.","o autor poderá alterar o pedido independentemente de nova citação Réu.","o autor não poderá alterar o pedido, em nenhuma hipótese.","o autor não poderá alterar o pedido, salvo promovendo nova citação do Réu, que poderá responder no prazo de 15 dias."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2016 • TEC 337638","source":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2016","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/337638","year":2016,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-337732","sourceQuestionId":"337732","t":"cpc-m11","moduleId":"cpc-m11","q":"Gabriel, pessoa capaz, foi revel em ação na qual Marcelo formulou pedido de condenação. Gabriel não possui patrono nos autos. Em razão da revelia,","o":["se Gabriel vier a intervir no processo, o Juiz deverá dar nova oportunidade para apresentação de contestação.","o pedido de Marcelo será necessariamente acolhido, pois a revelia induz presunção absoluta de veracidade dos fatos afirmados na inicial.","o Juiz deverá nomear curador especial para Gabriel, o qual poderá contestar por negativa geral, invertendo-se o ônus da prova.","o Juiz determinará a intimação pessoal de Gabriel a fim de que compareça nos autos, sob pena de confesso.","os prazos, em relação a Gabriel, correrão independentemente de intimação, a partir da publicação de cada ato decisório."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/Oficial de Justiça Avaliador Federal/2016 • TEC 337732","source":"FCC - AJ TRT23/TRT 23/Judiciária/Oficial de Justiça Avaliador Federal/2016","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/337732","year":2016,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"});
